--.. the equipped Index trail multiplies every rep too, on top of the headband (2026-09-23):
--.. CucumberAdventure writes data.CucumberCollection.Equipped = zone once that biome's Index is
--.. complete (Families[zone]); no trail, or a trail the profile has not earned, is 1x
function GymService.TrailMultiplier(data)
	local collection = type(data.CucumberCollection) == "table" and data.CucumberCollection or nil
	local zone = collection and collection.Equipped
	if type(zone) ~= "string" or type(collection.Families) ~= "table" or collection.Families[zone] ~= true then return 1 end
	return CollectionTrails.StrengthMultOf(zone)
end

function GymService.StrengthPerRep(data)
	return 2 ^ (Level(data, "BenchPress") - 1) * GymService.HeadbandMultiplier(data) * GymService.TrailMultiplier(data)
end

